def compute(vars):
    stock_awards = vars["v1"]
    total_purchase_price = vars["v2"]

    if total_purchase_price == 0:
        return {"value": None, "trace": {"stock_awards": stock_awards, "total_purchase_price": total_purchase_price}}

    portion = stock_awards / total_purchase_price
    return {
        "value": portion,
        "trace": {
            "stock_awards": stock_awards,
            "total_purchase_price": total_purchase_price,
            "portion": portion,
            "output_meta": {"currency": None, "scale": None, "unit": "ratio"},
        },
    }
